/// Generates Dart, TypeScript and ARB output from the JSON contracts.
library;

import 'dart:convert';
import 'dart:io';

const _header =
    'GENERATED by tools/gen_contracts from /contracts. '
    'Do not edit; run `melos run generate`.';

/// Converts `UPPER_SNAKE` to `lowerCamel`.
String camel(String upperSnake) {
  final parts = upperSnake.toLowerCase().split('_');
  return parts.first +
      parts.skip(1).map((p) => p[0].toUpperCase() + p.substring(1)).join();
}

/// Builds every generated file as a map of repo-relative path to content.
///
/// [existingArb] is the current `app_en.arb`; only its `error*` keys are
/// replaced, so hand-written strings survive regeneration.
Map<String, String> generate({
  required Map<String, Object?> errors,
  required Map<String, Object?> constants,
  required Map<String, Object?> demo,
  required String existingArb,
}) {
  for (final name in demo.keys) {
    if (!constants.containsKey(name)) {
      throw StateError('constants.demo.json overrides unknown constant $name');
    }
  }
  return {
    'packages/saff_core/lib/src/failure/failure_code.g.dart': _dartFailureCodes(
      errors,
    ),
    'packages/saff_domain/lib/src/constants/saff_constants.g.dart':
        _dartConstants(constants, demo),
    'functions/src/contracts/errors.generated.ts': _tsErrors(errors),
    'functions/src/contracts/constants.generated.ts': _tsConstants(
      constants,
      demo,
    ),
    'app/lib/l10n/app_en.arb': _arb(errors, existingArb),
  };
}

Map<String, Object?> _entry(Map<String, Object?> m, String code) =>
    (m[code]! as Map).cast<String, Object?>();

String _dartFailureCodes(Map<String, Object?> errors) {
  final b = StringBuffer()
    ..writeln('// $_header')
    ..writeln()
    ..writeln("import 'package:saff_core/src/failure/failure_kind.dart';")
    ..writeln()
    ..writeln('/// Every failure code in `contracts/errors.json`.')
    ..writeln('enum FailureCode {');
  final codes = errors.keys.toList();
  for (var i = 0; i < codes.length; i++) {
    final code = codes[i];
    final e = _entry(errors, code);
    final https = e['httpsCode'];
    b
      ..writeln('  /// ${e['description']}')
      ..writeln('  ${camel(code)}(')
      ..writeln("    '$code',")
      ..writeln('    kind: FailureKind.${e['kind']},')
      ..writeln('    severity: FailureSeverity.${e['severity']},')
      ..writeln('    retryable: ${e['retryable']},')
      ..writeln('    httpsCode: ${https == null ? 'null' : "'$https'"},')
      ..writeln("    messageKey: '${e['messageKey']}',")
      ..writeln('  )${i == codes.length - 1 ? ';' : ','}');
  }
  b
    ..writeln()
    ..writeln('  const FailureCode(')
    ..writeln('    this.wire, {')
    ..writeln('    required this.kind,')
    ..writeln('    required this.severity,')
    ..writeln('    required this.retryable,')
    ..writeln('    required this.httpsCode,')
    ..writeln('    required this.messageKey,')
    ..writeln('  });')
    ..writeln()
    ..writeln('  /// The code as written in the catalog and on the wire.')
    ..writeln('  final String wire;')
    ..writeln()
    ..writeln('  /// The family of failure.')
    ..writeln('  final FailureKind kind;')
    ..writeln()
    ..writeln('  /// How serious the failure is.')
    ..writeln('  final FailureSeverity severity;')
    ..writeln()
    ..writeln('  /// Whether retrying can succeed.')
    ..writeln('  final bool retryable;')
    ..writeln()
    ..writeln('  /// The matching Firebase callable error code, if any.')
    ..writeln('  final String? httpsCode;')
    ..writeln()
    ..writeln('  /// The ARB key of the user-facing message.')
    ..writeln('  final String messageKey;')
    ..writeln()
    ..writeln('  /// Finds a code by its wire name, or null if unknown.')
    ..writeln('  static FailureCode? fromWire(String wire) {')
    ..writeln('    for (final code in values) {')
    ..writeln('      if (code.wire == wire) return code;')
    ..writeln('    }')
    ..writeln('    return null;')
    ..writeln('  }')
    ..writeln('}');
  return b.toString();
}

String _dartValue(Map<String, Object?> c, Object value) =>
    c['unit'] == 'ms' ? 'Duration(milliseconds: $value)' : '$value';

String _dartConstants(
  Map<String, Object?> constants,
  Map<String, Object?> demo,
) {
  final names = constants.keys.toList();
  final b = StringBuffer()
    ..writeln('// $_header')
    ..writeln()
    ..writeln('/// Product constants (`contracts/constants.json`).')
    ..writeln('///')
    ..writeln(
      '/// Use [production] unless the dev flavor asked for demo timing;',
    )
    ..writeln('/// see [resolve].')
    ..writeln('final class SaffConstants {')
    ..writeln('  /// Creates a full set of constants.')
    ..writeln('  const SaffConstants({');
  for (final n in names) {
    b.writeln('    required this.${camel(n)},');
  }
  b
    ..writeln('  });')
    ..writeln()
    ..writeln('  /// The values every release build uses.')
    ..writeln('  static const production = SaffConstants(');
  for (final n in names) {
    final c = _entry(constants, n);
    b.writeln('    ${camel(n)}: ${_dartValue(c, c['value']!)},');
  }
  b
    ..writeln('  );')
    ..writeln()
    ..writeln(
      '  /// [production] with `contracts/constants.demo.json` applied.',
    )
    ..writeln('  static const demo = SaffConstants(');
  for (final n in names) {
    final c = _entry(constants, n);
    b.writeln('    ${camel(n)}: ${_dartValue(c, demo[n] ?? c['value']!)},');
  }
  b
    ..writeln('  );')
    ..writeln()
    ..writeln('  /// Picks the constants for a build.')
    ..writeln('  ///')
    ..writeln('  /// Demo values apply only when [allowDemo] (the dev flavor)')
    ..writeln('  /// and [demoRequested] (`DEMO_TIMING`) are both true, so a')
    ..writeln('  /// prod build ignores the request.')
    ..writeln('  static SaffConstants resolve({')
    ..writeln('    required bool allowDemo,')
    ..writeln('    required bool demoRequested,')
    ..writeln('  }) => allowDemo && demoRequested ? demo : production;');
  for (final n in names) {
    final c = _entry(constants, n);
    final type = c['unit'] == 'ms' ? 'Duration' : 'int';
    b
      ..writeln()
      ..writeln('  /// ${c['description']}')
      ..writeln('  final $type ${camel(n)};');
  }
  b.writeln('}');
  return b.toString();
}

String _tsKey(String name, Map<String, Object?> c) =>
    camel(name) + (c['unit'] == 'ms' ? 'Ms' : '');

String _tsErrors(Map<String, Object?> errors) {
  final b = StringBuffer()
    ..writeln('// $_header')
    ..writeln()
    ..writeln('/** Every failure code in contracts/errors.json. */')
    ..writeln('export const ERROR_CATALOG = {');
  for (final code in errors.keys) {
    final e = _entry(errors, code);
    final https = e['httpsCode'];
    b
      ..writeln('  $code: {')
      ..writeln('    kind: "${e['kind']}",')
      ..writeln('    severity: "${e['severity']}",')
      ..writeln('    retryable: ${e['retryable']},')
      ..writeln('    httpsCode: ${https == null ? 'null' : '"$https"'},')
      ..writeln('    messageKey: "${e['messageKey']}",')
      ..writeln('  },');
  }
  b
    ..writeln('} as const;')
    ..writeln()
    ..writeln('/** A code from the catalog. */')
    ..writeln('export type FailureCode = keyof typeof ERROR_CATALOG;');
  return b.toString();
}

String _tsConstants(
  Map<String, Object?> constants,
  Map<String, Object?> demo,
) {
  final b = StringBuffer()
    ..writeln('// $_header')
    ..writeln()
    ..writeln('/** Product constants; durations are in milliseconds. */')
    ..writeln('export interface Constants {');
  for (final n in constants.keys) {
    b.writeln('  readonly ${_tsKey(n, _entry(constants, n))}: number;');
  }
  b
    ..writeln('}')
    ..writeln()
    ..writeln('/** The values every deployed function uses. */')
    ..writeln('export const PRODUCTION_CONSTANTS: Constants = {');
  for (final n in constants.keys) {
    final c = _entry(constants, n);
    b.writeln('  ${_tsKey(n, c)}: ${c['value']},');
  }
  b
    ..writeln('};')
    ..writeln()
    ..writeln('/** Production values with the demo overlay applied. */')
    ..writeln('export const DEMO_CONSTANTS: Constants = {');
  for (final n in constants.keys) {
    final c = _entry(constants, n);
    b.writeln('  ${_tsKey(n, c)}: ${demo[n] ?? c['value']},');
  }
  b
    ..writeln('};')
    ..writeln()
    ..writeln('/**')
    ..writeln(
      ' * Picks the constants for a run. Demo values apply only when the',
    )
    ..writeln(' * emulator is in use and DEMO_TIMING was requested.')
    ..writeln(' */')
    ..writeln('export function resolveConstants(options: {')
    ..writeln('  readonly allowDemo: boolean;')
    ..writeln('  readonly demoRequested: boolean;')
    ..writeln('}): Constants {')
    ..writeln('  return options.allowDemo && options.demoRequested')
    ..writeln('    ? DEMO_CONSTANTS')
    ..writeln('    : PRODUCTION_CONSTANTS;')
    ..writeln('}');
  return b.toString();
}

String _arb(Map<String, Object?> errors, String existingArb) {
  final existing = existingArb.trim().isEmpty
      ? <String, Object?>{}
      : (jsonDecode(existingArb) as Map).cast<String, Object?>();
  final merged = <String, Object?>{'@@locale': 'en'};
  for (final entry in existing.entries) {
    if (entry.key == '@@locale') continue;
    if (entry.key.startsWith('error') || entry.key.startsWith('@error')) {
      continue;
    }
    merged[entry.key] = entry.value;
  }
  final keys = <String, String>{
    for (final code in errors.keys)
      (_entry(errors, code)['messageKey']! as String):
          _entry(errors, code)['message']! as String,
  };
  for (final key in keys.keys.toList()..sort()) {
    merged[key] = keys[key];
  }
  return '${const JsonEncoder.withIndent('  ').convert(merged)}\n';
}

/// Reads the contracts under [repoRoot] and returns the generated files.
Map<String, String> generateFromRepo(String repoRoot) {
  Map<String, Object?> read(String path) =>
      (jsonDecode(File('$repoRoot/$path').readAsStringSync()) as Map)
          .cast<String, Object?>();
  final arb = File('$repoRoot/app/lib/l10n/app_en.arb');
  return generate(
    errors: read('contracts/errors.json'),
    constants: read('contracts/constants.json'),
    demo: read('contracts/constants.demo.json'),
    existingArb: arb.existsSync() ? arb.readAsStringSync() : '',
  );
}
